def refuse_duplicate_transactions(apps, schema_editor):
    """One provider transaction pays for one payment. If two payments already share one, that is
    a double credit to look at by hand before the unique constraint can be added."""
    Payment = apps.get_model("schools", "Payment")
    duplicates = (
        Payment.objects.exclude(provider_transaction_id="")
        .values("provider", "provider_transaction_id")
        .annotate(n=Count("id"))
        .filter(n__gt=1)
    )
    if duplicates.exists():
        listed = ", ".join(f"{d['provider']}:{d['provider_transaction_id']}" for d in duplicates[:20])
        raise RuntimeError(
            "These provider transactions are recorded on more than one payment (a double credit): "
            f"{listed}. Check them, clear provider_transaction_id on the wrong ones, then migrate again."
        )


